SET NAMES utf8mb4;

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>该实施方案围绕扩大农产品消费、释放多样化和品质化消费潜力展开，从优化供给、创新流通、激活市场和强化保障等方面作出系统部署，旨在提升绿色优质农产品供给能力和消费转化效率。</p><h3>二、支持重点</h3><ul><li>在供给端推动“三品一标”提升、品质评价和质量分级，鼓励开发新型加工产品和地方特色食品。</li><li>在流通端强调产供销精准衔接，支持创新节庆展会消费平台、丰富消费场景并发挥电商平台带动作用。</li><li>在市场端强化品牌引领、消费科普、农文旅融合和内外贸联动，形成更广泛的消费带动效应。</li></ul><h3>三、实施要求</h3><p>政策强调加强部门协同，完善财政金融支持和全链条监管机制，推动产地、渠道和消费端联动，形成覆盖供给、流通和市场的整体推进体系。</p><h3>四、申报提示</h3><p>展示项目时可重点准备品牌建设、产销对接、活动组织和消费带动效果等材料，突出政策导向与商城应用场景的结合。</p>'
WHERE policies_id = 'demo_policy_20260324_05';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>科技特派员服务强调把农业技术、种养方案和经营指导送到基层，通过常态化下沉服务提升农业生产效率、科技应用水平和经营组织能力。公开案例显示，当地已建设各类示范基地15个，推广新技术、新品种、新模式82项，形成了较强的技术带动效应。</p><h3>二、支持重点</h3><ul><li>围绕粮油、果蔬、中药材和地方特色产业开展田间指导、技术咨询和示范推广。</li><li>全年开展培训15次、累计培训5255人次，并通过工作站和示范基地持续提供技术服务。</li><li>推动科技成果转化和经营辅导，公开案例中已转化成果5项、解决技术问题1764次。</li></ul><h3>三、实施要求</h3><p>政策实践强调依托工作站、示范基地和专家团队建立常态化服务机制，推动科技服务从单次指导向持续帮扶、成果转化和品牌培育延伸。</p><h3>四、申报提示</h3><p>项目展示时可重点准备产业需求、技术清单、示范场景、培训计划和服务成效等材料，突出科技服务与产业增效的结合度。</p>'
WHERE policies_id = 'demo_policy_20260324_04';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>“数商兴农年”活动以扩大农产品网络销售、培育县域电商主体和提升数字经营能力为重点，推动农村电商从单次促销走向常态化运营。公开工作安排体现出培训提升、直播推介、线上促销和示范培育等4个方面的任务导向。</p><h3>二、支持重点</h3><ul><li>组织农户、合作社负责人和电商从业者参加店铺运营、短视频制作、直播带货等专题培训。</li><li>围绕特色农产品开展直播专场、线上促销、区域品牌宣传和节庆展销活动，提升曝光和转化效率。</li><li>引导经营主体与平台、商超、供应链企业建立稳定合作，完善县域电商服务和数据统计能力。</li></ul><h3>三、实施要求</h3><p>活动组织应结合地方主导产业、重要消费节点和平台资源统筹安排，明确组织主体、活动节奏和效果评估方式，形成可延续的助农电商活动机制。</p><h3>四、申报提示</h3><p>建议准备培训记录、活动方案、直播场次、销售数据和品牌传播效果等材料，便于后续展示和项目复盘。</p>'
WHERE policies_id = 'demo_policy_20260324_03';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>该类地方政策围绕农产品市场提档升级、产销衔接和流通保障展开，重点提升城市市场对优质农产品的承接能力和保供服务水平。根据公开通知，支持方向至少涵盖批发市场建设、标准化菜市场改造、冷链物流节点完善和便民零售网点发展4类内容。</p><h3>二、支持重点</h3><ul><li>支持批发市场完善交易、分拣、仓储、冷链、检测和数字化管理等配套设施。</li><li>支持菜市场标准化升级改造，配置智慧管理系统、电子秤、监控和数字化设备。</li><li>支持冷链配送中心、物流园区和社区零售网点协同建设，提升农产品进城效率和终端服务能力。</li></ul><h3>三、实施要求</h3><p>项目实施需围绕市场升级、流通效率提升和公共服务改善形成清晰的建设方案，并同步做好资金安排、进度管理和绩效评估。</p><h3>四、申报提示</h3><p>建议重点准备建设方案、市场运营数据、产销协作证明和资金预算等材料，突出设施提升与民生服务效果。</p>'
WHERE policies_id = 'demo_policy_20260324_02';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>该意见聚焦农村电商高质量发展，明确提出用5年时间基本建成设施完善、主体活跃、流通顺畅、服务高效的农村电商服务体系，并提出培育约100个农村电商“领跑县”、1000家县域数字流通龙头企业、1000个县域直播电商基地和10000名农村电商带头人的阶段性目标。</p><h3>二、支持重点</h3><ul><li>围绕县乡村三级流通体系，完善冷链仓储、寄递配送、共配站点和电商公共服务能力。</li><li>支持家庭农场、合作社、农业企业等经营主体发展网销业务，提升产品上行和品牌建设能力。</li><li>推进直播电商、数字消费场景和便民服务融合，增强农村电商持续运营基础。</li></ul><h3>三、实施要求</h3><p>政策强调把设施建设、主体培育、品牌推广和人才培训统筹推进，并与数字乡村、农村寄递物流体系和县域商业体系建设协同衔接，形成长期可运行的农村电商发展机制。</p><h3>四、申报提示</h3><p>项目展示时可重点准备县域网销数据、物流配套情况、品牌成果和带农增收成效等材料，突出项目可复制性和持续运营能力。</p>'
WHERE policies_id = 'demo_policy_20260324_01';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>围绕乡村振兴重点帮扶县发展需求，进一步完善金融、产业、人才和项目配套支持，增强重点地区自我发展能力。</p><h3>二、支持重点</h3><ul><li>加大信贷投放和财政金融协同支持，缓解重点帮扶县融资难题。</li><li>支持特色产业培育、农产品加工和县域商业体系建设，提升产业带动能力。</li><li>强化基础设施、公共服务和人才培养等重点领域保障，夯实乡村振兴基础。</li><li>鼓励金融机构、龙头企业和社会力量参与重点帮扶县建设。</li></ul><h3>三、实施要求</h3><p>各地要结合实际细化配套措施，明确项目储备、资金使用和绩效评价要求，推动政策落地见效。</p><h3>四、申报提示</h3><p>重点关注资金投向、项目成熟度、带农增收效果和后续运营能力，提前准备项目方案及相关证明材料。</p>'
WHERE policies_id = '1f58b81775f74362bf88a388fc792308';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>支持农业产业化龙头企业做大做强，提升加工转化、品牌建设和联农带农水平，推动乡村产业高质量发展。</p><h3>二、支持重点</h3><ul><li>支持依法注册、经营稳定、主营业务清晰、信用记录良好的经营主体申报。</li><li>支持完善原料基地、加工能力和销售渠道，提升产业链带动作用。</li><li>支持品牌建设、技术改造和冷链仓储，增强企业持续发展能力。</li></ul><h3>三、实施要求</h3><p>突出联农带农机制、产业基础和示范带动效果，优先培育成长性强、示范作用明显的企业。</p><h3>四、申报提示</h3><p>建议准备经营数据、基地情况、联农带农证明、品牌材料和项目实施方案等核心资料。</p>'
WHERE policies_id = '294c9c66a52241759e75030014201b4e';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>持续扩大脱贫地区农产品销售规模，提升消费帮扶的组织化、品牌化和常态化水平，进一步拓宽重点地区农产品销售渠道。</p><h3>二、支持重点</h3><ul><li>推进政府采购、机关食堂和企事业单位对接消费帮扶产品，扩大稳定采购需求。</li><li>完善沪滇、粤滇等产销协作渠道，形成长期订单和对口协作机制。</li><li>支持线上平台、展销活动和直播带货等新渠道拓展，提升产品曝光度。</li><li>培育示范企业、帮扶专柜和区域品牌，增强消费帮扶可持续性。</li></ul><h3>三、实施要求</h3><p>结合年度工作计划明确重点品类、时间节点和责任主体，持续跟踪推进成效并做好宣传推广。</p><h3>四、申报提示</h3><p>重点关注采购比例、销售规模、带农效果和活动佐证材料，确保项目数据真实、过程可追溯。</p>'
WHERE policies_id = '507850c118d74d4f8688824792af12b8';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>通过系统化培训和示范带动，培育一批乡村振兴致富带头人，提升乡村经营管理能力和产业组织能力。</p><h3>二、支持重点</h3><ul><li>面向村干部、合作社负责人、家庭农场主、返乡创业人员和农村电商经营者开展培训。</li><li>围绕经营管理、品牌建设、市场营销、直播电商和项目申报等内容设置课程。</li><li>通过实训观摩、案例辅导和导师跟踪服务提升培训实效。</li></ul><h3>三、实施要求</h3><p>坚持分层分类组织培训，突出实操性、针对性和持续性，并与后续项目储备和示范培育衔接。</p><h3>四、申报提示</h3><p>报名时可准备个人经营情况、带动农户情况和培训需求说明，便于后续精准匹配课程资源。</p>'
WHERE policies_id = '629834e80d9a4667ae68ba1b806eba82';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>围绕重点帮扶县和特色农业主产区开展金融创新试点，完善乡村振兴融资服务体系，提升金融资源服务农业农村的覆盖面。</p><h3>二、支持重点</h3><ul><li>推广乡村振兴贷、产业链贷等特色信贷产品，满足不同经营主体融资需求。</li><li>探索经营权、农机具、仓储设施等抵质押融资，缓解抵押物不足问题。</li><li>推动银行、保险、担保机构建立风险共担机制，降低金融机构放贷顾虑。</li><li>完善整村授信、驻点服务和数字化风控等配套机制。</li></ul><h3>三、实施要求</h3><p>坚持试点先行、分类推进，强化贷后管理、风险监测和服务评估，提升试点可复制性。</p><h3>四、申报提示</h3><p>建议重点准备融资需求说明、经营数据、可抵押资源情况和产业发展计划等材料。</p>'
WHERE policies_id = '659fbf22a2b347309a83dc4550a92da9';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>支持县域农产品经营主体拓展线上销售渠道，提升品牌推广、直播运营和网络销售能力，增强电商带农增收效果。</p><h3>二、支持重点</h3><ul><li>给予平台入驻、店铺装修、直播推广和流量投放补贴，降低线上运营成本。</li><li>支持冷链包装、品牌设计、短视频宣传等营销服务，提升产品展示效果。</li><li>鼓励打造区域公用品牌和网销爆款农产品，形成示范带动作用。</li><li>支持参加产销对接、直播节庆和特色农产品推广活动。</li></ul><h3>三、实施要求</h3><p>突出线上销售实绩、品牌打造和带农成效，推动电商主体与本地产业链协同发展。</p><h3>四、申报提示</h3><p>建议同步准备店铺链接、订单截图、培训记录和带农证明等材料，便于核验和绩效统计。</p>'
WHERE policies_id = '6f6d3076c99b43cf8082255fd40f3073';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>推动农业科技力量下沉基层，围绕重点产业开展技术服务和成果转化，提升乡村产业科技支撑能力。</p><h3>二、支持重点</h3><ul><li>从科研院所、高校、推广机构和涉农企业中选派具备实践经验的科技人员开展服务。</li><li>围绕种植、养殖、加工等关键环节开展技术指导，帮助解决实际问题。</li><li>建设示范基地，推广新品种、新技术和新模式，带动经营主体提质增效。</li></ul><h3>三、实施要求</h3><p>依托工作站、项目支持和考核激励机制，推动科技服务长期化、制度化和成果化。</p><h3>四、申报提示</h3><p>建议结合当地产业需求准备技术服务清单、示范场景和培训计划，提升对接效率。</p>'
WHERE policies_id = 'b36832ad8d4240b19ae27f0f71ab2976';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>围绕优势特色产业统筹推进标准化生产、精深加工、品牌营销和农旅融合发展，打造现代农业产业园示范样板。</p><h3>二、支持重点</h3><ul><li>支持核心种养基地、仓储冷链和加工配套设施建设，夯实产业基础。</li><li>支持公共品牌打造、质量追溯和数字农业应用，提升产业竞争力。</li><li>支持龙头企业、合作社和家庭农场协同发展，完善联农带农机制。</li><li>鼓励产业园与文旅、研学、电商等场景结合，拓展增值空间。</li></ul><h3>三、实施要求</h3><p>申报主体需围绕主导产业形成完整实施方案，明确建设目标、配套措施和联农带农成效。</p><h3>四、申报提示</h3><p>建议重点准备产业规划、建设方案、资金测算、预期效益和带农机制等材料。</p>'
WHERE policies_id = 'bcae27d563fa4bdf80265703ef771929';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>通过特色农产品保险补贴，降低经营主体参保成本，提升农业生产抗风险能力和灾后恢复能力。</p><h3>二、支持重点</h3><ul><li>重点覆盖苹果、中药材、高原夏菜、小杂粮等地方特色农产品，优先向主产区推广。</li><li>对符合条件的保险产品给予保费补贴，鼓励保险机构优化保障责任。</li><li>支持主产区开展特色农产品保险扩面提质，提高覆盖范围和参保率。</li></ul><h3>三、实施要求</h3><p>发生保险事故后，按规定开展查勘、定损和赔付，确保理赔流程规范透明、赔付及时到位。</p><h3>四、申报提示</h3><p>建议提前确认保险责任范围、免赔条款和报案时限，并妥善保存种养记录等基础资料。</p>'
WHERE policies_id = 'd89db230c4fe45bcb766a34724994847';

UPDATE policies
SET content = '<h3>一、政策目标</h3><p>推动黑土地保护利用常态化、制度化开展，提升耕地质量和地力恢复水平，促进农业可持续发展。</p><h3>二、支持重点</h3><ul><li>对实施秸秆还田、轮作休耕、有机肥替代等措施的主体给予支持。</li><li>支持保护性耕作、地力提升和示范片区建设，增强黑土地可持续利用能力。</li><li>推动建立黑土地保护长效机制，形成可复制、可推广的经验做法。</li></ul><h3>三、实施要求</h3><p>由乡镇组织摸底申报，县级农业农村部门审核确认后按标准兑现补贴资金，并做好验收和台账管理。</p><h3>四、申报提示</h3><p>建议同步准备耕地利用记录、实施照片、面积证明和技术措施说明，便于审核和后续核验。</p>'
WHERE policies_id = 'e3e0109cfef740a4903ff88496a634e1';
